class TestRefactor(unittest.TestCase):

    def test_data_parser(self):
        self.assertEqual(DataParser.parse_value("1.234,56", FieldType.NUMBER), 1234.56)
        self.assertEqual(DataParser.parse_value("1,234.56", FieldType.NUMBER), 1234.56)
        self.assertEqual(DataParser.parse_value("2023.12.25", FieldType.DATE), "2023-12-25")
        self.assertEqual(DataParser.parse_value("25/12/2023", FieldType.DATE), "2023-12-25")

    def test_migration_layer(self):
        legacy_config = {
            "regions": [
                {"name": "test", "x": 0, "y": 0, "w": 10, "h": 10, "type": "text"}
            ]
        }
        normalized = GenericPDFParser._normalize_config(legacy_config)

        # Check defaults
        stage = normalized["stages"][0]
        region = stage["regions"][0]
        self.assertEqual(region["extractionMethod"], ExtractionMethod.RAW_TEXT)

        legacy_table = {
            "regions": [
                {"name": "tbl", "type": "table", "tableExtractionMode": "auto", "x":0, "y":0, "w":10, "h":10}
            ]
        }
        norm_table = GenericPDFParser._normalize_config(legacy_table)
        region_t = norm_table["stages"][0]["regions"][0]
        self.assertEqual(region_t["tableStrategy"], TableStrategy.PHYSICAL_GRID)

    @patch('app.services.parsers.generic.pdfplumber')
    def test_extraction_dispatch(self, mock_pdfplumber):
        # Mock PDF
        mock_page = MagicMock()
        mock_page.width = 100
        mock_page.height = 100
        mock_page.crop.return_value.extract_text.return_value = "Hello World"

        mock_pdf = MagicMock()
        mock_pdf.pages = [mock_page]
        mock_pdfplumber.open.return_value.__enter__.return_value = mock_pdf

        config = {
            "stages": [{
                "id": "s1", 
                "regions": [
                    {
                        "name": "r1", "x": 0, "y": 0, "w": 50, "h": 50, 
                        "type": "text", "extractionMethod": "text"
                    }
                ]
            }]
        }

        result = GenericPDFParser.parse("dummy.pdf", config)
        self.assertEqual(result["r1"], "Hello World")

if __name__ == '__main__':
    unittest.main()

