    """
    Extracts table data based on typographic clustering (whitespace/alignment).
    Simple implementation: Groups words into lines.
    Future improvement: Detect columns by X-gaps.
    """
    if not words: return []

    lines = {}
    for w in words:
        # Group by approximate Y-coordinate (4px tolerance)
        y = round(w["top"] / 4) * 4
