@classmethod
def _extract_table_typographic(cls, words: List[Dict]) -> List[Dict[str, Any]]:
    """
    Extracts table data based on typographic clustering.
    1. Groups words into lines.
    2. Automatically detects column gaps across all lines.
    3. Bins words into detected columns.
    """
    if not words: return []

    # 1. Group words into lines
    sorted_words = sorted(words, key=lambda w: w["top"])
    lines = []
    current_line = []
    Y_THRESHOLD = 10 

    if sorted_words:
        current_line.append(sorted_words[0])
        last_top = sorted_words[0]["top"]
        for w in sorted_words[1:]:
            if abs(w["top"] - last_top) < Y_THRESHOLD:
                current_line.append(w)
            else:
                current_line.sort(key=lambda w: w["x0"])
                lines.append(current_line)
                current_line = [w]
            last_top = w["top"]
        if current_line:
            current_line.sort(key=lambda w: w["x0"])
            lines.append(current_line)

    # 2. Identify Column Gaps (Horizontal whitespace detection)
    min_x = min(w['x0'] for w in words)
    max_x = max(w['x1'] for w in words)
    width = int(max_x - min_x) + 1
    occupancy = [0] * width

    for w in words:
        start = int(w['x0'] - min_x)
        end = int(w['x1'] - min_x)
        for i in range(start, end):
            if 0 <= i < width: occupancy[i] += 1

    gaps = []
    in_gap = False
    gap_start = 0
    MIN_GAP_WIDTH = 5 # Minimum pixels for a column gap

    for i in range(width):
        if occupancy[i] == 0:
            if not in_gap:
                in_gap = True
                gap_start = i
        else:
            if in_gap:
                in_gap = False
                if (i - gap_start) >= MIN_GAP_WIDTH:
                    gaps.append((gap_start + min_x, i + min_x))

    col_boundaries = []
    if not gaps:
        col_boundaries = [(min_x, max_x)]
    else:
        col_boundaries.append((min_x, gaps[0][0]))
        for i in range(len(gaps) - 1):
            col_boundaries.append((gaps[i][1], gaps[i+1][0]))
        col_boundaries.append((gaps[-1][1], max_x))

    # 3. Bin words into columns
    rows = []
    for line in lines:
        row_data = {}
        for i, (c_start, c_end) in enumerate(col_boundaries):
            # Tolerance to catch slightly overlapping words
            cell_words = [w["text"] for w in line if c_start - 2 <= (w["x0"] + w["x1"])/2 <= c_end + 2]
            row_data[f"Col {i+1}"] = " ".join(cell_words).strip()

        if any(row_data.values()):
            rows.append(row_data)

    return rows

const handleMouseMove = (e: React.MouseEvent) => {
  if ((!isDrawing && !isResizing) || !canvasRef.current) return;
  const rect = canvasRef.current.getBoundingClientRect();
  const currentX = e.clientX - rect.left;
  const currentY = e.clientY - rect.top;
  const containerW = canvasRef.current.offsetWidth;
  const containerH = canvasRef.current.offsetHeight;

  if (isResizing && initialRegion && resizeHandle) {
      // ... resizing logic ...
      updateRegionBatch({ x: newX, y: newY, w: newW, h: newH });
      return;
  }

  let width = currentX - startPos.x;
  let height = currentY - startPos.y;
  let rx = width > 0 ? startPos.x : currentX;
  let ry = height > 0 ? startPos.y : currentY;
  let rw = Math.abs(width);
  let rh = Math.abs(height);

  // If drawing a sub-field, restrict to parent region
  if (isDrawingField && selectedRegion) {
      const parentX = (selectedRegion.x / 100) * containerW;
      const parentY = (selectedRegion.y / 100) * containerH;
      const parentW = (selectedRegion.w / 100) * containerW;
      const parentH = (selectedRegion.h / 100) * containerH;

      rx = Math.max(parentX, rx);
      ry = Math.max(parentY, ry);
      rw = Math.min(parentW - (rx - parentX), rw);
      rh = Math.min(parentH - (ry - parentY), rh);
  }

  setCurrentRect({ x: rx, y: ry, w: rw, h: rh });
};

