    """
    Cleans up common OCR artifacts in table cells (newlines, spaces, basic symbols).
    """
    cleaned_rows = []
    for row in rows:
        new_row = {}
        for k, v in row.items():
            if isinstance(v, str):
                # Join newline-split OCR text with spaces or separators
                # If it looks like a date or time fragment, join cleanly
